def compute(vars):
    values = {
        2018: vars["v1"],
        2017: vars["v2"],
        2016: vars["v3"],
    }
    year = min(values, key=values.get)
    return {
        "value": values[year],
        "trace": {
            "values_by_year": values,
            "lowest_year": year,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None,
            },
        },
    }
